package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Entities_unescape_TriageGen1Test {

    private Entities entities;
    private StringWriter writer;

    @Before
    public void setUp() {
        entities = new Entities();
        writer = new StringWriter();
    }

    @Test
    public void testUnescape_NoAmpersand() throws IOException {
        entities.unescape(writer, "hello world");
        assertEquals("hello world", writer.toString());
    }

    @Test
    public void testUnescape_NoSemicolon() throws IOException {
        entities.unescape(writer, "hello &world");
        assertEquals("hello &world", writer.toString());
    }

    @Test
    public void testUnescape_AmpersandBeforeSemicolon() throws IOException {
        // Tests the logic: if (amphersandIdx != -1 && amphersandIdx < semiColonIdx)
        entities.unescape(writer, "test &abc&def;");
        assertEquals("test &abc&def;", writer.toString());
    }

    @Test
    public void testUnescape_NamedEntity() throws IOException {
        entities.addEntity("quot", 34);
        entities.unescape(writer, "a&quot;b");
        assertEquals("a\"b", writer.toString());
    }

    @Test
    public void testUnescape_UnknownNamedEntity() throws IOException {
        entities.unescape(writer, "a&unknown;b");
        assertEquals("a&unknown;b", writer.toString());
    }

    @Test
    public void testUnescape_EmptyEntity() throws IOException {
        entities.unescape(writer, "a&;b");
        assertEquals("a&;b", writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntity() throws IOException {
        entities.unescape(writer, "&#65;");
        assertEquals("A", writer.toString());
    }

    @Test
    public void testUnescape_HexEntityUpper() throws IOException {
        entities.unescape(writer, "&#x41;");
        assertEquals("A", writer.toString());
    }

    @Test
    public void testUnescape_HexEntityLower() throws IOException {
        entities.unescape(writer, "&#x41;");
        // Note: The code uses switch(isHexChar) which catches 'X' and 'x'. 
        // If 'x' is provided, it executes the hex branch.
        entities.unescape(writer, "&#x41;");
        assertEquals("A", writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntityInvalid() throws IOException {
        entities.unescape(writer, "&#abc;");
        assertEquals("&#abc;", writer.toString());
    }

    @Test
    public void testUnescape_HexEntityInvalid() throws IOException {
        entities.unescape(writer, "&#xG1;");
        assertEquals("&#xG1;", writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntityTooShort() throws IOException {
        // Tests entityContentLen > 1 check
        entities.unescape(writer, "&#;");
        assertEquals("&#;", writer.toString());
    }

    @Test
    public void testUnescape_MixedContent() throws IOException {
        entities.addEntity("lt", 60);
        entities.unescape(writer, "text &lt; &#60; &#x3c; &invalid; &");
        assertEquals("text < < < &invalid; &", writer.toString());
    }

    @Test
    public void testUnescape_DecimalEntityWithNonHexChar() throws IOException {
        // Tests the default case in the switch: isHexChar is not X or x
        // If entityContent is "&#123;" -> isHexChar is '1'. 
        // The switch goes to default, but it parses '123' as decimal.
        entities.unescape(writer, "&#123;");
        assertEquals("{", writer.toString());
    }

    @Test
    public void testUnescape_ComplexEdgeCase() throws IOException {
        entities.addEntity("amp", 38);
        entities.unescape(writer, "&&amp;;&amp;");
        // 1. First '&' -> nextIdx 1. semiColonIdx for first '&' is at &amp; index.
        // But wait, the loop logic:
        // string: &&amp;;&amp;
        // i=0: c='&', nextIdx=1, semiColonIdx=5 (&amp;;)
        // amphersandIdx = string.indexOf('&', 1) = 1.
        // 1 < 5 is true. So it writes '&' and continues.
        // i=1: c='&', nextIdx=2, semiColonIdx=5.
        // amphersandIdx = string.indexOf('&', 2) = 6.
        // 6 < 5 is false.
        // entityContent = "amp". entityValue = 38. writes 38. i = 5.
        // i=6: c='&', nextIdx=7, semiColonIdx = -1. writes '&'.
        // i=7: c='a'...
        // This tests the nested logic thoroughly.
        entities.unescape(writer, "&&amp;");
        assertEquals("&&", writer.toString());
    }
}
